// Wire-compatibility tests for src/remote/e2e/index.ts (@noble/* impl).
//
// Pins the TS impl byte-for-byte against:
//   - remote-e2e/vectors/basic.json            (generated by the Rust crate)
//   - remote-e2e/vectors/libsodium_compat.json (captured from the previous
//     libsodium-wrappers impl; also asserted by remote-e2e/tests/libsodium_compat.rs)
//
// Run: node --test src/lib/__tests__/remoteE2e.test.mjs
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { x25519 } from '@noble/curves/ed25519.js'
import {
  E2eError,
  Session,
  deriveEffectivePsk,
  deriveSession,
  generateKeypair,
  hostFingerprint,
  keypairFromBytes,
  ready,
} from '../../remote/e2e/index.ts'

const readVector = (name) =>
  JSON.parse(readFileSync(new URL(`../../../remote-e2e/vectors/${name}`, import.meta.url), 'utf8'))
const basic = readVector('basic.json')
const compat = readVector('libsodium_compat.json')

const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')
const unhex = (s) => Uint8Array.from(s.match(/../g) ?? [], (x) => parseInt(x, 16))
const utf8 = (s) => new TextEncoder().encode(s)
const kp = (i) => keypairFromBytes(unhex(compat.keypairs[i].pk), unhex(compat.keypairs[i].sk))

test('ready() resolves (no runtime init needed)', async () => {
  assert.equal(await ready(), undefined)
})

test('Rust basic vector: session key, seal, open, fingerprint', () => {
  const psk = unhex(basic.psk_hex)
  const a = keypairFromBytes(unhex(basic.pk_a_hex), unhex(basic.sk_a_hex))
  const b = keypairFromBytes(unhex(basic.pk_b_hex), unhex(basic.sk_b_hex))
  const sa = deriveSession(psk, a, b.publicKey)
  const sb = Session.derive(psk, b, a.publicKey)
  assert.equal(hex(sa.keyBytes()), basic.session_key_hex)
  assert.equal(hex(sb.keyBytes()), basic.session_key_hex)
  assert.equal(sa.sealWithNonce(utf8(basic.plaintext_utf8), unhex(basic.nonce_hex)), basic.cipher_b64)
  assert.equal(new TextDecoder().decode(sb.open(basic.cipher_b64)), basic.plaintext_utf8)
  assert.equal(hostFingerprint(a.publicKey), basic.host_fingerprint_hex)
})

test('public key from fixed secret matches crypto_scalarmult_base', () => {
  for (const { sk, pk } of compat.keypairs) {
    assert.equal(hex(x25519.getPublicKey(unhex(sk))), pk, sk)
  }
})

test('X25519 DH matches crypto_scalarmult (incl. high-bit / non-canonical u)', () => {
  for (const { sk, pk, dh } of compat.dh) {
    assert.equal(hex(x25519.getSharedSecret(unhex(sk), unhex(pk))), dh, `${sk} x ${pk}`)
  }
})

test('low-order peer keys are rejected as degenerate (Rust WeakKex)', () => {
  for (const pk of compat.weak_peer_keys) {
    assert.throws(
      () => Session.derive(unhex('00'), kp(0), unhex(pk)),
      (e) => e instanceof E2eError && e.message === 'x25519 shared secret is degenerate',
      pk,
    )
  }
})

test('session key derivation matches for both roles', () => {
  for (const { a, b, psk_hex, key_hex } of compat.sessions) {
    assert.equal(hex(Session.derive(unhex(psk_hex), kp(a), kp(b).publicKey).keyBytes()), key_hex)
    assert.equal(hex(Session.derive(unhex(psk_hex), kp(b), kp(a).publicKey).keyBytes()), key_hex)
  }
})

test('psk longer than 64 bytes throws (BLAKE2b key ceiling), empty psk is E2eError', () => {
  assert.throws(() => Session.derive(unhex('cd'.repeat(65)), kp(0), kp(1).publicKey))
  assert.throws(() => Session.derive(new Uint8Array(0), kp(0), kp(1).publicKey), E2eError)
})

test('sealWithNonce reproduces the libsodium ciphertexts; open round-trips', () => {
  const psk = unhex(compat.sessions[0].psk_hex)
  const sa = Session.derive(psk, kp(0), kp(1).publicKey)
  const sb = Session.derive(psk, kp(1), kp(0).publicKey)
  for (const { nonce_hex, plaintext_hex, cipher_b64 } of compat.seals) {
    assert.equal(sa.sealWithNonce(unhex(plaintext_hex), unhex(nonce_hex)), cipher_b64)
    assert.equal(hex(sb.open(cipher_b64)), plaintext_hex)
  }
})

test('open: strict base64 + frame/version/auth errors match libsodium', () => {
  const psk = unhex(compat.sessions[0].psk_hex)
  const sb = Session.derive(psk, kp(1), kp(0).publicKey)
  for (const c of compat.open_cases) {
    if (c.error === undefined) {
      assert.equal(hex(sb.open(c.cipher_b64)), c.plaintext_hex, JSON.stringify(c.cipher_b64))
    } else {
      assert.throws(
        () => sb.open(c.cipher_b64),
        (e) => e instanceof E2eError && e.message === c.error,
        JSON.stringify(c.cipher_b64),
      )
    }
  }
})

test('hostFingerprint matches', () => {
  for (const { pk, fp } of compat.fingerprints) {
    assert.equal(hostFingerprint(unhex(pk)), fp)
  }
})

test('deriveEffectivePsk matches', () => {
  for (const { link, secret2, psk_hex } of compat.effective_psk) {
    assert.equal(hex(deriveEffectivePsk(link, secret2)), psk_hex)
  }
})

test('fresh keypairs: public = X25519 base mult, round trip, random nonces', () => {
  const host = generateKeypair()
  const ctrl = generateKeypair()
  assert.equal(host.secretKey.length, 32)
  assert.equal(hex(x25519.getPublicKey(host.secretKey)), hex(host.publicKey))
  const psk = utf8('a-strong-pairing-psk-32-bytes!!!')
  const sHost = Session.derive(psk, host, ctrl.publicKey)
  const sCtrl = Session.derive(psk, ctrl, host.publicKey)
  const msg = utf8('{"kind":"cmd","action":"start_run"}')
  const c1 = sCtrl.seal(msg)
  const c2 = sCtrl.seal(msg)
  assert.notEqual(c1, c2)
  assert.equal(hex(sHost.open(c1)), hex(msg))
  assert.throws(() => Session.derive(utf8('wrong'), host, ctrl.publicKey).open(c1), E2eError)
})
